const crypto = require('crypto');
const BOT_TOKEN = String(
  $vars.TELEGRAM_BOT_TOKEN
  ?? $env.TELEGRAM_BOT_TOKEN
  ?? "",
).trim();

if (!BOT_TOKEN) {
  throw new Error("Falta configurar TELEGRAM_BOT_TOKEN en n8n.");
}
const CATEGORIES = new Set('Hogar|Muebles|Electrodomésticos|Infantil|Ropa|Libros|Música y cine|Tecnología|Móviles y telefonía|Informática|Deportes y ocio|Bicicletas|Juegos y videojuegos|Manualidades y coleccionismo|Jardín y bricolaje|Otros'.split('|'));
const CONDITIONS = new Set(['Como nuevo', 'Bueno', 'Aceptable', 'Roto']);
const NEIGHBORHOODS = new Set('Arcas Reales|Arturo Eyries|Barrio España|Batallas|Belén - Pilarica|Campo Grande|Caño Argales|Circular|Ciudad de la Comunicación|Coto de Simancas|Covaresa|Cuatro de Marzo|Delicias - Arco de Ladrillo|Delicias - Canterac|El Berrocal|El Peral|El Pinar|Girón|Hospital|Huerta del Rey|La Antigua - Santa Cruz|La Farola|La Overuela|La Rubia|La Victoria|Las Flores|Las Villas - Valparaíso|Pajarillos Altos|Pajarillos Bajos|Parque Alameda - Paula López|Parquesol|Pilarica - Los Santos|Pinar de Jalón|Plaza de Toros|Plaza España|Plaza Mayor|Polígono Argales|Polígono Industrial la Mora|Polígono San Cristóbal|Puente Duero|Puente Jardín|Rondilla|San Isidro|San Pablo - San Nicolás|San Pedro Regalado|Soto de Medinilla|Urbanización El Pichón|Urbanización El Plantío|Urbanización Entrepinos|Urbanización Las Aceñas|Vadillos|Villa del Prado|Aldeamayor de San Martín|Arroyo de la Encomienda|Boecillo|Cabezón de Pisuerga|Casasola de Esgueva|Castronuevo de Esgueva|Cigales|Ciguñuela|Cistérniga|Corcos|Cubillas de Santa Marta|Fuensaldaña|Geria|Laguna de Duero|La Pedraja de Portillo|Mucientes|Olmos de Esgueva|Piña de Esgueva|Quintanilla de Trigueros|Renedo de Esgueva|Robladillo|San Martín de Valvení|Santovenia de Pisuerga|Simancas|Trigueros del Valle|Tudela de Duero|Valdestillas|Valoria la Buena|Viana de Cega|Villabáñez|Villanubla|Villanueva de Duero|Villanueva de los Infantes|Villarmentero de Esgueva|Villavaquerín|Wamba|Zaratán|Aguilarejo|Granja Muedra|Herrera de Duero|La Flecha|San Andrés'.split('|'));
const incoming = $input.first() ?? {};
const input = incoming.json ?? {};
const inputBinary = incoming.binary ?? {};
function output(json) { return [{ json, binary: inputBinary }]; }
function invalid(error) { return output({ ok: false, valid: false, error }); }
function parseQueryString(value) {
  const fields = {};
  try {
    for (const part of String(value).split('&')) {
      const separator = part.indexOf('=');
      if (separator < 0) continue;
      const key = decodeURIComponent(part.slice(0, separator).replace(/\+/g, ' '));
      const fieldValue = decodeURIComponent(part.slice(separator + 1).replace(/\+/g, ' '));
      fields[key] = fieldValue;
    }
  } catch {
    return null;
  }
  return {
    get(key) { return fields[key] ?? null; },
    entries() { return Object.entries(fields); },
  };
}
let body = input.body ?? input;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { return invalid('invalid_json'); } }
const multipartPayload = body?.payload ?? input.payload;
if (typeof multipartPayload === 'string') { try { body = JSON.parse(multipartPayload); } catch { return invalid('invalid_payload'); } } else if (multipartPayload && typeof multipartPayload === 'object') { body = multipartPayload; }
const initData = typeof body.initData === 'string' ? body.initData.trim() : '';
if (!initData) return invalid('telegram_init_data_missing');
const params = parseQueryString(initData);
if (!params) return invalid('telegram_init_data_malformed');
const receivedHash = params.get('hash') ?? '';
const authDate = Number(params.get('auth_date'));
if (!/^[a-f0-9]{64}$/i.test(receivedHash) || !Number.isInteger(authDate)) return invalid('telegram_init_data_invalid');
const now = Math.floor(Date.now() / 1000);
if (authDate > now + 60 || now - authDate > 86400) return invalid('telegram_init_data_expired');
const dataCheckString = [...params.entries()].filter(([key]) => key !== 'hash').sort(([left], [right]) => left.localeCompare(right)).map(([key, value]) => key + '=' + value).join('\n');
const secretKey = crypto.createHmac('sha256', 'WebAppData').update(BOT_TOKEN).digest();
const expectedHash = crypto.createHmac('sha256', secretKey).update(dataCheckString).digest('hex');
const received = Buffer.from(receivedHash, 'hex');
const expected = Buffer.from(expectedHash, 'hex');
if (received.length !== expected.length || !crypto.timingSafeEqual(received, expected)) return invalid('telegram_identity_invalid');
let user;
try { user = JSON.parse(params.get('user') ?? '{}'); } catch { return invalid('telegram_user_invalid'); }
if (!user || !Number.isSafeInteger(user.id)) return invalid('telegram_user_invalid');
const consent = body.consent && typeof body.consent === 'object' ? body.consent : {};
const consentVersion = typeof consent.version === 'string' ? consent.version.trim() : '';
if (consent.accepted !== true) return invalid('consent_required');
if (consentVersion !== 'sv-publish-2026-08-17-v3') return invalid('consent_version_invalid');
const photoEntries = Object.entries(inputBinary).filter(([name, file]) => /^photo_[01]$/.test(name) && file?.data).sort(([left], [right]) => left.localeCompare(right));
if (photoEntries.length > 2) return invalid('too_many_photos');
function binarySizeInBytes(file) {
  const raw = file.fileSize ?? file.size;
  if (typeof raw === 'number' && Number.isFinite(raw)) return raw;
  if (typeof raw === 'string') {
    const normalized = raw.trim().toLowerCase().replace(',', '.');
    const match = normalized.match(/^(\d+(?:\.\d+)?)\s*(b|kb|kib|mb|mib|gb|gib)?$/);
    if (match) {
      const amount = Number(match[1]);
      const unit = match[2] ?? 'b';
      const multiplier = { b: 1, kb: 1000, kib: 1024, mb: 1000 ** 2, mib: 1024 ** 2, gb: 1000 ** 3, gib: 1024 ** 3 }[unit];
      return amount * multiplier;
    }
  }
  if (typeof file.data === 'string') {
    const padding = file.data.endsWith('==') ? 2 : file.data.endsWith('=') ? 1 : 0;
    return Math.max(0, Math.floor(file.data.length * 3 / 4) - padding);
  }
  return NaN;
}
for (const [, file] of photoEntries) { const mimeType = file.mimeType ?? file.mimetype ?? ''; const size = binarySizeInBytes(file); if (!['image/jpeg', 'image/png', 'image/webp'].includes(mimeType)) return invalid('photo_type_invalid'); if (!Number.isFinite(size) || size <= 0 || size > 5 * 1024 * 1024) return invalid('photo_too_large'); }
const item = body.item && typeof body.item === 'object' ? body.item : {};
const title = typeof item.title === 'string' ? item.title.trim() : '';
const category = typeof item.category === 'string' ? item.category.trim() : '';
const zone = typeof item.zone === 'string' ? item.zone.trim() : '';
const condition = typeof item.condition === 'string' ? item.condition.trim() : '';
const description = typeof item.description === 'string' ? item.description.trim() : '';
const durationDays = Number(item.duration_days ?? 14);
if (title.length < 3 || title.length > 80) return invalid('title_invalid');
if (!CATEGORIES.has(category)) return invalid('category_invalid');
if (!NEIGHBORHOODS.has(zone)) return invalid('zone_invalid');
if (!CONDITIONS.has(condition)) return invalid('condition_invalid');
if (description.length > 600) return invalid('description_too_long');
if (![7, 14, 30].includes(durationDays)) return invalid('duration_invalid');
const displayName = [user.first_name, user.last_name].filter((value) => typeof value === 'string' && value.trim()).join(' ').trim().slice(0, 120) || 'Vecindad';
const ownerTelegramId = String(user.id);
const publicItemId = crypto.randomBytes(6).toString('base64url');
const expiresAt = new Date(Date.now() + durationDays * 24 * 60 * 60 * 1000).toISOString();
return output({ ok: true, valid: true, public_id: publicItemId, item_id: publicItemId, title, description, category, zone, condition, status: 'available', expires_at: expiresAt, owner_telegram_id: ownerTelegramId, owner_display_name: displayName, owner_username: typeof user.username === 'string' ? user.username : '', interest_count: 0, favorite_count: 0, consent_accepted: true, consent_version: consentVersion, consent_at: new Date().toISOString(), photo_count: photoEntries.length, Fotos: [], image_url: '' });

const validated = $input.first()?.json ?? {};
const source = $('Validate Telegram and item').first() ?? {};
if (validated.valid !== true) return [{ json: validated, binary: source.binary ?? {} }];
const webhook = $('Webhook').first()?.json ?? {};
let body = webhook.body ?? webhook;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = {}; } }
const multipartPayload = body?.payload ?? webhook.payload;
if (typeof multipartPayload === 'string') { try { body = JSON.parse(multipartPayload); } catch { body = {}; } } else if (multipartPayload && typeof multipartPayload === 'object') { body = multipartPayload; }
const requestedPublicId = typeof body?.item?.public_id === 'string' ? body.item.public_id.trim() : '';
const publicIdPattern = /^[A-Za-z0-9_-]{6,80}$/;
const publicItemId = publicIdPattern.test(requestedPublicId) ? requestedPublicId : validated.public_id ?? validated.item_id;
return [{ json: { ...validated, public_id: publicItemId, item_id: publicItemId }, binary: source.binary ?? {} }];

const request = $('Reuse client publish id').first()?.json ?? {};
const source = $('Reuse client publish id').first() ?? {};
const requestedId = String(request.public_id ?? request.item_id ?? '').trim();
const rows = $input.all();
const found = rows.map(({ json }) => ({ json, fields: json.fields ?? json })).find(({ fields }) => String(fields.public_id ?? fields['item-id'] ?? '') === requestedId);
if (!found) return [{ json: { ...request, create_new: true }, binary: source.binary ?? {} }];
const fields = found.fields;
if (String(fields.owner_telegram_id ?? '') !== String(request.owner_telegram_id ?? '')) return [{ json: { ok: false, valid: false, error: 'publish_id_conflict', error_code: 'publish_id_conflict', create_new: false }, binary: source.binary ?? {} }];
const status = String(fields.status ?? 'hidden').toLowerCase();
if (status === 'hidden') return [{ json: { ok: false, valid: false, error: 'publication_pending', error_code: 'publication_pending', item_id: requestedId, public_id: requestedId, retryable: true, create_new: false }, binary: source.binary ?? {} }];
return [{ json: { ok: true, valid: true, deduplicated: true, item_id: requestedId, public_id: requestedId, title: fields.title ?? request.title ?? '', status, message: 'Publicado correctamente', create_new: false }, binary: source.binary ?? {} }];

const source = $input.first() ?? {};
const sourceJson = source.json ?? {};
const binary = source.binary ?? {};
const names = Object.keys(binary).filter((name) => /^photo_[01]$/.test(name) && binary[name]).sort();
const photoPayloads = [];

for (const [index, name] of names.entries()) {
  const file = binary[name];
  const buffer = await this.helpers.getBinaryDataBuffer(0, name);
  photoPayloads.push({
    base64: buffer.toString('base64'),
    filename: file.fileName ?? `photo_${index}.jpg`,
    mimeType: file.mimeType ?? file.mimetype ?? 'image/jpeg',
  });
}

return [{
  json: {
    ...sourceJson,
    photo_payloads: photoPayloads,
  },
  binary,
}];

const prepared = $('Prepare photo uploads').first()?.json ?? {};
const created = $('Create NocoDB row').first()?.json ?? {};
const rowId = created.id ?? created.Id ?? created.fields?.id ?? created.fields?.Id ?? '';
if (!rowId) throw new Error('NocoDB no devolvió el ID de la fila creada.');
const photos = Array.isArray(prepared.photo_payloads) ? prepared.photo_payloads : [];

return photos.map((photo, index) => ({
  json: {
    ...created,
    row_id: rowId,
    photo_index: index,
    photo_base64: photo.base64,
    photo_filename: photo.filename ?? `photo_${index}.jpg`,
    photo_mime_type: photo.mimeType ?? 'image/jpeg',
  },
}));

const created = $('Create NocoDB row').first()?.json ?? {};
const rowId = created.id ?? created.Id ?? created.fields?.id ?? created.fields?.Id ?? '';
if (!rowId) throw new Error('NocoDB no devolvió el ID de la fila creada.');
return [{ json: { ...created, row_id: rowId, status: 'available' } }];

const current = $input.first()?.json ?? {};
const created = $('Create NocoDB row').first()?.json ?? {};
const fields = current.fields ?? current;
const createdFields = created.fields ?? created;
const publicId = fields.public_id ?? fields['item-id'] ?? createdFields.public_id ?? createdFields['item-id'] ?? '';
const rawAttachments = fields.photos ?? createdFields.photos ?? fields.Fotos ?? createdFields.Fotos ?? [];
const attachments = Array.isArray(rawAttachments) ? rawAttachments : [];
const imageUrls = attachments.map((attachment) => attachment?.url ?? attachment?.signedUrl ?? attachment?.signed_url ?? '').filter(Boolean);
return [{ json: { ok: true, public_id: publicId, item_id: publicId, title: fields.title ?? createdFields.title ?? '', status: fields.status ?? createdFields.status ?? 'available', image_url: fields.image_url ?? imageUrls[0] ?? null, image_urls: imageUrls, message: 'Publicado correctamente' } }];
